changeSet.sql:
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'preparation_time_min', trim(rpd.preparation_time_minutes::text) FROM restaurant_product_details rpd WHERE rpd.preparation_time_minutes IS NOT NULL ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'kitchen_department', trim(rpd.kitchen_department) FROM restaurant_product_details rpd WHERE rpd.kitchen_department IS NOT NULL AND trim(rpd.kitchen_department) <> '' ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'combo_component', 'true' FROM restaurant_product_details rpd WHERE rpd.is_combo_component = TRUE ON CONFLICT (product_id, field_key) DO NOTHING;
